import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        String[] kata = {"java", "php", "java", "go", "php", "java"};

        final Map<String, Integer> hitung = new LinkedHashMap<String, Integer>();
        for (String k : kata) {
            hitung.put(k, hitung.getOrDefault(k, 0) + 1);
        }
        System.out.println(hitung);

        List<String> urut = new ArrayList<String>(hitung.keySet());
        Collections.sort(urut, new Comparator<String>() {
            public int compare(String a, String b) {
                return hitung.get(b) - hitung.get(a);
            }
        });

        for (String k : urut) {
            System.out.println(k + ": " + hitung.get(k));
        }

        System.out.println("Kata unik: " + hitung.size());
        System.out.println("Total kata: " + kata.length);
    }
}

